package l2tp

import (
	"fmt"
	"net"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode"

	"openpass/internal/model"
)

var ownedName = regexp.MustCompile(`^op[0-9a-f]{8}$`)
var domainLabel = regexp.MustCompile(`^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$`)

// Validate also protects the pppd options file generated by OpenWrt's l2tp.sh,
// which quotes credentials without escaping embedded quotes or backslashes.
func Validate(n model.Node) error {
	if n.ID == "" || len(n.ID) > 128 {
		return fmt.Errorf("L2TP 节点 ID 无效")
	}
	if n.Type != "l2tp" {
		return fmt.Errorf("不是 L2TP 节点")
	}
	if n.Username == "" || n.Password == "" {
		return fmt.Errorf("L2TP 用户名和密码不能为空")
	}
	for _, credential := range []string{n.Username, n.Password} {
		if len(credential) > 256 {
			return fmt.Errorf("L2TP 用户名或密码过长")
		}
		for _, ch := range credential {
			if unicode.IsControl(ch) || ch == '"' || ch == '\\' {
				return fmt.Errorf("L2TP 用户名或密码不能包含控制字符、双引号或反斜杠")
			}
		}
	}
	if n.Address == "" || len(n.Address) > 253 || strings.TrimSpace(n.Address) != n.Address {
		return fmt.Errorf("L2TP 服务器地址无效")
	}
	if ip := net.ParseIP(n.Address); ip != nil {
		if ip.To4() == nil {
			return fmt.Errorf("L2TP 服务器暂仅支持 IPv4 或域名")
		}
	} else {
		for _, label := range strings.Split(strings.TrimSuffix(n.Address, "."), ".") {
			if !domainLabel.MatchString(label) {
				return fmt.Errorf("L2TP 服务器地址无效")
			}
		}
	}
	if n.Port < 0 || n.Port > 65535 {
		return fmt.Errorf("L2TP 端口无效")
	}
	if n.MTU != 0 && (n.MTU < 1280 || n.MTU > 1460) {
		return fmt.Errorf("L2TP MTU 必须在 1280 到 1460 之间")
	}
	return nil
}

func configFor(n model.Node) map[string]string {
	server := n.Address
	if n.Port != 0 && n.Port != 1701 {
		server += ":" + strconv.Itoa(n.Port)
	}
	mtu := n.MTU
	if mtu == 0 {
		mtu = 1400
	}
	return map[string]string{
		"": "interface", "proto": "l2tp", "server": server,
		"username": n.Username, "password": n.Password,
		"mtu": strconv.Itoa(mtu), "keepalive": "5 5",
		"defaultroute": "0", "peerdns": "0", "ipv6": "0", "auto": "0",
		"openpass_owned": "1", "openpass_node": n.ID,
	}
}

func sortedKeys(c map[string]string) []string {
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// parseNetwork consumes uci show output in memory. Neither the full config
// nor failed command output may be included in errors: both contain secrets.
func parseNetwork(data []byte) map[string]map[string]string {
	out := map[string]map[string]string{}
	for _, line := range strings.Split(string(data), "\n") {
		key, value, ok := strings.Cut(line, "=")
		if !ok || !strings.HasPrefix(key, "network.") {
			continue
		}
		section, field, _ := strings.Cut(strings.TrimPrefix(key, "network."), ".")
		if !ownedName.MatchString(section) {
			continue
		}
		if out[section] == nil {
			out[section] = map[string]string{}
		}
		out[section][field] = unquoteUCI(value)
	}
	return out
}

func unquoteUCI(s string) string {
	// uci show writes apostrophes as the shell sequence '\''.
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "'\\''", "'")
	}
	return s
}

func isOwned(name string, c map[string]string) bool {
	return ownedName.MatchString(name) && c[""] == "interface" && c["proto"] == "l2tp" &&
		c["openpass_owned"] == "1" && c["openpass_node"] != "" && InterfaceName(c["openpass_node"]) == name
}

func sameConfig(actual, desired map[string]string) bool {
	// Do not trust only the checksum: administrators can edit UCI manually.
	for k, value := range desired {
		if actual[k] != value {
			return false
		}
	}
	// A user-supplied PPP option could replace the expected device name or
	// alter routing. Rebuild our own section if any extra option is present.
	for k := range actual {
		if _, ok := desired[k]; !ok {
			return false
		}
	}
	return true
}
